"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The conversion rate of a list of sessions. See SPEC.md section 1."""
    hits = sum(1 for e in events if e["converted"] is True)
    return hits / len(events) if events else 0.0


def pooled_conversion_rate(groups):
    """The pooled conversion rate across groups of sessions. See SPEC.md section 2."""
    total = sum(len(events) for events in groups.values())
    hits = sum(1 for events in groups.values() for e in events if e["converted"] is True)
    return hits / total if total else 0.0


def conversions_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    return sum(daily_counts[-days:]) if days else 0


def conversion_rate_by_group(groups):
    """The conversion rate of each group. See SPEC.md section 9."""
    return {name: conversion_rate(groups[name]) if groups[name] else None
            for name in sorted(groups)}


def longest_conversion_streak(daily_counts):
    """Longest run of days with converted sessions. See SPEC.md section 10."""
    best = cur = 0
    for c in daily_counts:
        if c > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""Load and prepare customer sessions for product analytics."""


def parse_session_log(lines):
    """Parse log lines into sessions. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid converted value")
        out.append({"id": id_, "day": day, "converted": flags[flag]})
    return out


def dedupe_sessions(events):
    """Remove duplicate sessions. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Daily counts of converted sessions. See SPEC.md section 6."""
    counts = [0] * max(0, end_day - start_day + 1)
    for e in events:
        if start_day <= e["day"] <= end_day and e["converted"] is True:
            counts[e["day"] - start_day] += 1
    return counts

import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}, {"converted": False}]) == 1 / 3
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {"small": [{"converted": True}],
              "large": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0
    assert pooled_conversion_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (8, 9)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected
    assert conversions_in_window([], days) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    assert parse_session_log([
        "\n", "  # comment,ignored,here\n", "  \t ",
        " a , 1 , 1 ", "b, -2, 0", "c,3,  ",
    ]) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": -2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,not-a-day,1", "a,1,true"])
def test_parse_invalid_line_reports_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", " # comment", " ", line])


def test_dedupe_duplicate_ids_keeps_last_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 1, "converted": True}
    last = {"id": "a", "day": 3, "converted": False}
    b = {"id": "b", "day": 3, "converted": True}
    c = {"id": "c", "day": 2, "converted": None}
    assert dedupe_sessions([first, b, c, last]) == [c, last, b]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_fills_gaps_and_ignores_outside_range():
    events = [
        {"day": 0, "converted": True}, {"day": 1, "converted": True},
        {"day": 1, "converted": True}, {"day": 2, "converted": None},
        {"day": 3, "converted": False}, {"day": 5, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], 1, 2) == [0, 0]


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 4, "converted": False}] * 5,
        "empty": [],
    }
    assert campaign_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"converted": True}], "empty": [],
              "a": [{"converted": True}], "b": [{"converted": False}]}
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_in_sorted_order():
    result = conversion_rate_by_group({"z": [], "b": [{"converted": False}],
                                       "a": [{"converted": True}, {"converted": None}]})
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 0.5, "b": 0.0, "z": None}


def test_longest_streak_only_counts_positive_consecutive_entries():
    assert longest_conversion_streak([1, 1, 0, 3, -1, 1, 1, 1, 0]) == 3
    assert longest_conversion_streak([-1, 0, -3]) == 0
    assert longest_conversion_streak([]) == 0
